import { AnyPointer, ResolverResult } from '../config';
import { resolveHttpResponse } from '../resolvers/http-response';

export async function routeImpulse(pointer: AnyPointer): Promise<ResolverResult> {
  switch (pointer.type) {
    case 'httpResponse':
      return resolveHttpResponse(pointer as any);
    default:
      return { shape: 'error', body: `Unknown pointer type: ${pointer.type}` };
  }
}
